SELECT COALESCE(SUM(amount), 0)
FROM purchase
WHERE purchase_date >= DATE '2025-01-01' AND purchase_date < DATE '2026-01-01';

SELECT COALESCE(ROUND((COUNT(*) FILTER (WHERE lower(status) = 'active')::numeric / NULLIF(COUNT(*)::numeric, 0)) * 100, 2), 0) AS porcentaje_activo
FROM subscription
WHERE start_date BETWEEN DATE '2024-01-01' AND DATE '2024-12-31';

SELECT game_id, title
FROM game
WHERE age_rating = 'M';

SELECT company_id, name
FROM company c
WHERE EXISTS (
  SELECT 1 FROM game g WHERE g.publisher_company_id = c.company_id
)
AND NOT EXISTS (
  SELECT 1 FROM game g2 WHERE g2.developer_company_id = c.company_id
)
ORDER BY name;

SELECT game.title, franchise.name
FROM game
JOIN franchise ON game.franchise_id = franchise.franchise_id;

SELECT DISTINCT game_id
FROM tournament
WHERE prize_pool > 10000;

SELECT status, SUM(total) AS total_facturado
FROM invoice
GROUP BY status;
